package org.sleepwell.app;
import android.app.Activity;import android.os.Bundle;import android.widget.LinearLayout;
/** Public static rationale destination; extras never read data or start a sync. */
public final class HealthSleepPrivacyActivity extends Activity {
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Sleep data permissions",this::finish);Design.space(body,20);Design.text(body,"Health Connect and your sleep",22,600,Design.INK);Design.space(body,16);Design.text(body,"SleepWell reads sleep sessions only when you choose Import and start a manual sync. It writes completed sleep sessions only when you choose Export and start sync. No audio files, microphone access or other health data types are requested for this feature.",15,400,Design.MUTED);Design.space(body,16);Design.text(body,"Imported records, original provider source, reported stages and local edits are stored on this phone. SleepWell has no account server, advertising or analytics service. A JSON backup you explicitly export includes historical source evidence, but excludes permission grants and live sync identities. Revoking access stops exchange; existing copies remain until you delete them. Health Connect and its other connected apps manage their own copies.",15,400,Design.MUTED);Design.space(body,16);Design.text(body,"You can revoke sleep permissions and delete Health Connect data in Android's Health Connect settings. SleepWell's Data & privacy controls remove local records. Provider writes may complete before a cancellation or failure is reported; stable client IDs make retries safe.",15,400,Design.MUTED);Design.button(body,"Done",true,this::finish);}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
